import 'dart:convert';
import 'package:test/test.dart';
import 'package:dpdf/src/io/image/image_data_factory.dart';

void main() {
  test(
      'GIF dictionary growth, clear and interlace against synthetic independent fixture',
      () {
// Generated from a 96x96 mathematical grayscale pattern using Pillow.
    final image = CraftImageDataFactory.create(base64.decode(
        ''));
    expect(image.getData(), [
      for (var y = 0; y < 96; y++)
        for (var x = 0; x < 96; x++) (x * 13 + y * 17 + x * y) % 256
    ]);
  });
}
